'use strict';
const products={oil:{name:'The Daily Oil',type:'Botanical face oil',price:38,image:'assets/ritual.jpg',size:'30 ml / 1 fl oz',description:'A small pause for your skin. This botanical face oil concept brings a gentle, nourishing step to your morning or evening ritual.',ritual:'Warm 2–3 drops between your palms, press gently onto clean skin, and take a slow breath.'},cream:{name:'The Soft Reset',type:'Everyday face cream',price:32,image:'assets/skin.jpg',size:'50 ml / 1.7 fl oz',description:'A softer start, a slower finish. A daily cream concept inspired by the quiet comfort of simple, thoughtful care.',ritual:'Smooth a small amount onto clean skin. Take your time. A little goes a long way.'},soak:{name:'The Slow Soak',type:'Botanical bath soak',price:28,image:'assets/bath.jpg',size:'250 g / 8.8 oz',description:'An invitation to switch off. A botanical bathing concept for those evenings when you need a little room to exhale.',ritual:'Scatter a small handful into warm running water. Set your phone aside and settle in.'}};
let cart={};try{const saved=JSON.parse(localStorage.getItem('rooted-bag')||'{}');for(const [id,n] of Object.entries(saved)){if(products[id]&&Number.isInteger(n)&&n>0)cart[id]=Math.min(n,99)}}catch{}
const $=s=>document.querySelector(s),bag=$('#bag'),detail=$('#detail');let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function persist(){try{localStorage.setItem('rooted-bag',JSON.stringify(cart))}catch{}renderBag()}
function renderBag(){const count=Object.values(cart).reduce((a,n)=>a+n,0);$('#cart-count').textContent=count;$('#bag-number').textContent=`(${count})`;$('#cart-open').setAttribute('aria-label',`Open shopping bag, ${count} items`);if(!count){$('#bag-items').innerHTML='<div class="bag-empty"><span aria-hidden="true">✳</span><p>A little room for something good.<br>Find a ritual to make your own.</p><button class="solid-button" id="explore-bag">Explore the essentials ↗</button></div>';$('#bag-summary').innerHTML='';return}$('#bag-items').innerHTML=Object.entries(cart).map(([id,n])=>{const p=products[id];return `<div class="bag-item"><img src="${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><p>${p.size}</p><div class="quantity"><button data-quantity="${id}" data-change="-1" aria-label="Decrease ${p.name} quantity">−</button><span aria-label="Quantity ${n}">${n}</span><button data-quantity="${id}" data-change="1" aria-label="Increase ${p.name} quantity">+</button></div></div><div><p>$${p.price*n}</p><button class="remove" data-remove="${id}" aria-label="Remove ${p.name}">Remove</button></div></div>`}).join('');$('#bag-summary').innerHTML=`<div class="bag-total"><span>Subtotal</span><span>$${Object.entries(cart).reduce((sum,[id,n])=>sum+products[id].price*n,0)}.00</span></div><button class="solid-button" id="explore-bag">Keep exploring ↗</button>`}
function add(id){if(!products[id])return;if((cart[id]||0)>=99){toast('Your bag already has 99 of this ritual.');return}cart[id]=(cart[id]||0)+1;persist();toast(`${products[id].name} — added to your bag`)}
function showDetails(id){const p=products[id];$('#detail-content').innerHTML=`<div class="detail-product"><img src="${p.image}" alt="${p.name}"><div><span class="label">${p.type} · ${p.size}</span><h2>${p.name}</h2><p>${p.description}</p><span class="label">Make it a ritual</span><p>${p.ritual}</p><button class="solid-button" data-add="${id}">Add to bag — $${p.price}</button><p style="font-size:9px;opacity:.6">Illustrative product. This concept store does not accept orders.</p></div></div>`;detail.showModal()}
const stories={ritual:{category:'Everyday rituals · 3 min read',title:'The art of doing a little less.',paragraphs:['Some days, the kindest thing you can do is make a little space. Between the first alarm and the first message, between getting home and getting on with the evening.','A ritual does not have to be elaborate. It can be a warm cloth on your face. A drop of oil pressed between your palms. Five minutes in the bath without something playing in the background.','Start with something you already do. Slow it down. Notice the temperature, the texture, the light in the room. Let that be enough.','There is no perfect routine to achieve. Just a small invitation to be here, in the ordinary, for a moment longer.']},nature:{category:'Closer to nature · 2 min read',title:'Let the outside in.',paragraphs:['A leaf on the windowsill. The changing light across a wall. A few stems in a glass. Nature does not always need a grand entrance.','Try moving a morning ritual closer to a window. Notice how the same room feels different as the light moves through the day. Open the window, if you can, and listen.','Bring home something small from a walk: a fallen leaf, a smooth stone, a twig with an interesting shape. Give it a place where you will see it.','These are simple reminders that the world is still growing, and that we are part of it. A little grounding can go a long way.']}};
const info={contact:{title:'Hello, from Rooted.',text:'Thanks for stopping by. ROOTED is a fictional brand and design concept, so there is no customer service inbox connected. Explore the essentials, read a field note, or try the demo newsletter to see the experience in action.'},delivery:{title:'Delivery & returns',text:'ROOTED is an illustrative design concept. The products and prices demonstrate a shopping experience; no orders, payments, deliveries, or returns are processed. You can explore the collection and save a demo bag on this device.'},care:{title:'A little product care',text:'The products shown here are concept examples. Follow the directions supplied by the manufacturer of any skincare product you actually use. Store your products as directed, and keep your everyday ritual simple.'},privacy:{title:'Your space, respected.',text:'This concept stores your demo bag and, if you submit the form, your newsletter email in this browser’s local storage. Nothing is submitted to a mailing service. Clear your browser’s site data to remove these details. Photography and fonts are bundled with the site.'},terms:{title:'A thoughtfully simple concept.',text:'ROOTED is a fictional botanical care brand created as an editorial design demonstration. Product images, descriptions, prices, and stories are illustrative. This website does not accept payment or place orders.'}};
$('#cart-open').addEventListener('click',()=>bag.showModal());document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.hasAttribute('data-close')){target.closest('dialog').close();return}if(target.dataset.add){add(target.dataset.add);return}if(target.dataset.details){showDetails(target.dataset.details);return}if(target.dataset.quantity){const id=target.dataset.quantity;cart[id]=Math.min(99,cart[id]+Number(target.dataset.change));if(cart[id]<=0)delete cart[id];persist();return}if(target.dataset.remove){delete cart[target.dataset.remove];persist();return}if(target.id==='explore-bag'){bag.close();$('#essentials').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return}if(target.dataset.story){const s=stories[target.dataset.story];$('#detail-content').innerHTML=`<article class="story-content"><span class="label">${s.category}</span><h2>${s.title}</h2>${s.paragraphs.map(p=>`<p>${p}</p>`).join('')}<span class="label">Field notes / Rooted</span></article>`;detail.showModal()}if(target.dataset.info){const i=info[target.dataset.info];$('#detail-content').innerHTML=`<div class="story-content"><span class="label">Rooted / A little help</span><h2>${i.title}</h2><p>${i.text}</p></div>`;detail.showModal()}});
for(const d of [bag,detail])d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close()});
$('#newsletter-form').addEventListener('submit',e=>{e.preventDefault();const email=$('#email').value.trim();if(!$('#email').checkValidity())return;try{localStorage.setItem('rooted-newsletter',email);$('#newsletter-status').textContent='You’re on the list — saved on this device. This is a demo signup.'}catch{$('#newsletter-status').textContent='Thanks for trying the signup. Browser storage is unavailable; nothing was saved.'}$('#email').value='';toast('A little good, received. Thanks for stopping by.')});
renderBag();$('#year').textContent=new Date().getFullYear();
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!reducedMotion&&'IntersectionObserver' in window){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}})},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
let ticking=false;function onScroll(){if(ticking)return;ticking=true;requestAnimationFrame(()=>{const y=window.scrollY;$('.header').classList.toggle('scrolled',y>35);if(!reducedMotion&&y<1200)document.querySelectorAll('[data-parallax]').forEach(el=>{el.style.transform=`translateY(${y*Number(el.dataset.parallax)}px)`});ticking=false})}addEventListener('scroll',onScroll,{passive:true});onScroll();

// Circular carousel: one vertical axis, counter-rotated image faces, manual control.
const imageCarousel=$('.carousel-window');
if(imageCarousel){
 const stage=$('.carousel-stage');
 const slides=[...imageCarousel.querySelectorAll('.carousel-slide')];
 const dots=[...document.querySelectorAll('.carousel-dots button')];
 let turnStep=0,drag=null;
 const wrap=n=>((n%slides.length)+slides.length)%slides.length;
 function renderCarousel(){const active=wrap(turnStep);stage.style.setProperty('--turn',`${-turnStep*120}deg`);$('.carousel-count').textContent=`${String(active+1).padStart(2,'0')} / 03`;dots.forEach((dot,i)=>dot.setAttribute('aria-pressed',String(i===active)));slides.forEach((slide,i)=>slide.setAttribute('aria-hidden',String(i!==active)))}
 function stepCarousel(delta){turnStep+=delta;renderCarousel()}
 function chooseImage(index){const active=wrap(turnStep);let delta=index-active;if(delta>1)delta-=3;if(delta< -1)delta+=3;stepCarousel(delta)}
 $('#image-previous').addEventListener('click',()=>stepCarousel(-1));
 $('#image-next').addEventListener('click',()=>stepCarousel(1));
 dots.forEach((dot,i)=>dot.addEventListener('click',()=>chooseImage(i)));
 imageCarousel.addEventListener('pointerdown',event=>{if(event.button!==0)return;drag={x:event.clientX,id:event.pointerId,step:turnStep};imageCarousel.classList.add('is-dragging');imageCarousel.setPointerCapture(event.pointerId)});
 imageCarousel.addEventListener('pointermove',event=>{if(!drag)return;const delta=event.clientX-drag.x;stage.style.setProperty('--turn',`${-drag.step*120+delta/imageCarousel.clientWidth*150}deg`)});
 function endDrag(event,cancelled=false){if(!drag)return;const saved=drag,delta=event.clientX-saved.x;drag=null;imageCarousel.classList.remove('is-dragging');if(imageCarousel.hasPointerCapture(saved.id))imageCarousel.releasePointerCapture(saved.id);turnStep=saved.step+(!cancelled&&Math.abs(delta)>Math.min(45,imageCarousel.clientWidth*.12)?(delta<0?1:-1):0);renderCarousel()}
 imageCarousel.addEventListener('pointerup',event=>endDrag(event));
 imageCarousel.addEventListener('pointercancel',event=>endDrag(event,true));
 imageCarousel.addEventListener('lostpointercapture',event=>endDrag(event,true));
 imageCarousel.addEventListener('keydown',event=>{if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();stepCarousel(event.key==='ArrowRight'?1:-1)}else if(event.key==='Home'||event.key==='End'){event.preventDefault();chooseImage(event.key==='Home'?0:slides.length-1)}});
 renderCarousel();
}
